node -e "
const https = require('https');
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Read API key
const settings = JSON.parse(fs.readFileSync('/data/data/com.termux/files/home/.iflow/settings.json', 'utf8'));
const apiKey = settings.apiKey;

// Download skill
const file = fs.createWriteStream('/data/data/com.termux/files/home/pptx.zip');
https.get('https://media.iflow.cn/cli_skills/20251222/pptx.zip', (response) => {
  response.pipe(file);
  file.on('finish', () => {
    file.close();
    console.log('Downloaded successfully');

    // Extract using Node.js
    try {
      const unzip = require('/data/data/com.termux/files/usr/lib/node_modules/@iflow-ai/iflow-cli/node_modules/adm-zip');
      const zip = new unzip('/data/data/com.termux/files/home/pptx.zip');
      zip.extractAllTo('/data/data/com.termux/files/home/.iflow/skills/pptx', true);
      console.log('Extracted successfully');
    } catch (e) {
      console.log('adm-zip not available, trying native unzip');
      execSync('unzip -o /data/data/com.termux/files/home/pptx.zip -d /data/data/com.termux/files/home/.iflow/skills/pptx');
      console.log('Extracted with native unzip');
    }
  });
}).on('error', (err) => {
  console.error('Download failed:', err.message);
});
" 2>&1

